import * as pdfjsLib from 'pdfjs-dist';
import nlp from 'compromise'; // You can still use this for other tasks
import spacy from 'spacy-nlp'; // Use a spaCy wrapper for JavaScript

// Initialize the spaCy model
const nlpModel = spacy.load('en_core_web_sm');

pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

const parsePDF = async (file) => {
  const reader = new FileReader();
  reader.readAsArrayBuffer(file);

  return new Promise((resolve, reject) => {
    reader.onload = async function () {
      try {
        const typedArray = new Uint8Array(reader.result);
        const pdf = await pdfjsLib.getDocument(typedArray).promise;

        if (!pdf || !pdf.numPages) {
          reject(new Error('Failed to load PDF document or no pages found.'));
          return;
        }

        let parsedText = '';

        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          const pageText = textContent.items.map((item) => item.str).join(' ');
          parsedText += pageText + '\n';
        }

        // Extract keywords using spaCy
        const keywords = await extractKeywords(parsedText);
        resolve({ parsedText, keywords });
      } catch (error) {
        reject(error);
      }
    };

    reader.onerror = function (error) {
      reject(error);
    };
  });
};

// Function to extract keywords using spaCy
const extractKeywords = async (text) => {
  const doc = await nlpModel(text);
  const keywords = [];

  doc.ents.forEach((ent) => {
    if (ent.label_ === 'ORG' || ent.label_ === 'GPE' || ent.label_ === 'PRODUCT') {
      keywords.push(ent.text); // Extract relevant named entities
    }
  });

  const nouns = doc.nouns().out('array'); // Extract nouns
  keywords.push(...nouns); // Combine with named entities

  return [...new Set(keywords)]; // Remove duplicates
};

export { parsePDF };
